import{_ as e,o as a,c as o,a2 as d}from"./chunks/framework.BM5YPQmL.js";const b=JSON.parse('{"title":"OCBL：故障排查与状态码","description":"","frontmatter":{},"headers":[],"relativePath":"zh/components/ocbl/ocbl-troubleshooting.md","filePath":"zh/components/ocbl/ocbl-troubleshooting.md"}'),c={name:"zh/components/ocbl/ocbl-troubleshooting.md"};function r(s,t,n,l,i,h){return a(),o("div",null,[...t[0]||(t[0]=[d(`<h1 id="ocbl-故障排查与状态码" tabindex="-1">OCBL：故障排查与状态码 <a class="header-anchor" href="#ocbl-故障排查与状态码" aria-label="Permalink to &quot;OCBL：故障排查与状态码&quot;">​</a></h1><p>OCBL 与恢复链报告什么，以及每份报告的含义。</p><h2 id="保留区记录-ocbl-写入的内容" tabindex="-1">保留区记录（OCBL 写入的内容） <a class="header-anchor" href="#保留区记录-ocbl-写入的内容" aria-label="Permalink to &quot;保留区记录（OCBL 写入的内容）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>含义</th></tr></thead><tbody><tr><td><code>magic</code> / <code>ver</code> / <code>size</code></td><td><code>&quot;OCB1&quot;</code>、版本 1、28 字节布局</td></tr><tr><td><code>kind</code></td><td>记录种类（见下）</td></tr><tr><td><code>stall</code></td><td>启动挂死所在的阶段</td></tr><tr><td><code>seq</code></td><td>判定时状态区的启动尝试序号</td></tr><tr><td><code>ts_unix</code></td><td>判定时刻，unix 秒（CMOS）</td></tr><tr><td><code>silence_sec</code></td><td>实测的无进度秒数</td></tr><tr><td><code>routed</code></td><td>1 = OCBL 已自动启动 OCIRE</td></tr><tr><td><code>boot_fails</code></td><td>连续判定失败次数</td></tr><tr><td><code>checksum</code></td><td>前置载荷字（小端 u32 视角）的反码和——区分真实记录与复位垃圾的校验</td></tr></tbody></table><h3 id="记录种类" tabindex="-1">记录种类 <a class="header-anchor" href="#记录种类" aria-label="Permalink to &quot;记录种类&quot;">​</a></h3><table tabindex="0"><thead><tr><th>种类</th><th>含义</th></tr></thead><tbody><tr><td>NONE</td><td>无记录（一次正常启动）</td></tr><tr><td>BOOT_FAILED</td><td>看门狗捕获、经判定的启动失败</td></tr><tr><td>USER_REQUEST</td><td>用户在菜单中选择了 OCIRE 条目</td></tr><tr><td>WAKE_FAILED</td><td>SLEEP_ARMED 在重启后仍然置位（唤醒向量崩溃或睡眠中死亡）</td></tr></tbody></table><h2 id="接管菜单-路由之后-位于-ocire" tabindex="-1">接管菜单（路由之后，位于 OCIRE） <a class="header-anchor" href="#接管菜单-路由之后-位于-ocire" aria-label="Permalink to &quot;接管菜单（路由之后，位于 OCIRE）&quot;">​</a></h2><p>两个阻塞菜单共享一个按键循环。<strong>其余按键一律忽略，且没有超时</strong> ——机器留在恢复环境，直到人做出决定。</p><h3 id="启动失败接管-连续两次判定失败" tabindex="-1">启动失败接管（连续两次判定失败） <a class="header-anchor" href="#启动失败接管-连续两次判定失败" aria-label="Permalink to &quot;启动失败接管（连续两次判定失败）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[R] 回滚到上一个 OCOS 版本</span></span>
<span class="line"><span>[C] 继续并再次尝试启动 OCOS</span></span></code></pre></div><h3 id="唤醒失败接管-sleep-armed-在重启后仍置位" tabindex="-1">唤醒失败接管（SLEEP_ARMED 在重启后仍置位） <a class="header-anchor" href="#唤醒失败接管-sleep-armed-在重启后仍置位" aria-label="Permalink to &quot;唤醒失败接管（SLEEP_ARMED 在重启后仍置位）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[W] 从睡眠唤醒失败。（诊断信息）</span></span>
<span class="line"><span>[R] 回滚到上一个 OCOS 版本</span></span>
<span class="line"><span>[C] 尝试正常启动 OCOS</span></span></code></pre></div><ul><li><code>[R]</code> 翻转 OCOS 的 A/B 槽标志（<code>next_B</code> / <code>ok_B</code> / <code>bootfail_B</code> 协议——与 GRUB 配置及 OCBL 扫描器实现的语义 相同）并重启。</li><li><code>[C]</code> 清除失败记录并重启进入 OCOS。</li><li><code>[W]</code> 打印唤醒失败诊断（判定时刻、静默时长、连续失败次数， 以及 SLEEP_ARMED 仍然置位的含义说明）。</li></ul><h2 id="解读一次启动失败" tabindex="-1">解读一次启动失败 <a class="header-anchor" href="#解读一次启动失败" aria-label="Permalink to &quot;解读一次启动失败&quot;">​</a></h2><p>OCIRE 把记录字段打印为修复建议：挂死阶段（0 BOOT / 1 KMAIN / 2 SCHED / 3 DRIVERS / 4 SERVICES / 5 L1_LAUNCHED / 6 L1_READY / 255 RUNTIME）、实测静默时长、启动失败计数与启动序号。低阶段 挂死且 <code>silence_sec</code> 大，指向硬件或内核早期问题；挂在 255 （RUNTIME）表示系统已起来、之后才挂死。</p><h2 id="hangat-诊断钩子" tabindex="-1">/HANGAT 诊断钩子 <a class="header-anchor" href="#hangat-诊断钩子" aria-label="Permalink to &quot;/HANGAT 诊断钩子&quot;">​</a></h2><p>当载荷卷上存在一个字节、内容为 <code>1</code>..<code>7</code> 的 <code>/HANGAT</code> 文件时， OCBL 在内核命令行追加 <code>oc.hang=N</code>，内核在记录完阶段 N 后立即 故意停机——阶段看门狗已布防，因此真实的 看门狗 -&gt; 复位 -&gt; 诊断 链路与生产环境完全一致地触发。<code>7</code> 在 L1_READY 之后、运行时心跳 运行中停机（运行时挂死场景）。该钩子让<strong>出货镜像</strong>无需测试专用 内核即可做失败演练；文件不存在时它是完整的无操作。</p><h2 id="监视器自禁用" tabindex="-1">监视器自禁用 <a class="header-anchor" href="#监视器自禁用" aria-label="Permalink to &quot;监视器自禁用&quot;">​</a></h2><p>若本次启动中固定监视页对 OCBL 不可用（BIOS：没有 E820 可用区域 覆盖它们；UEFI：AllocatePages 保留失败），整个监视器<strong>本次启动 自禁用</strong>——完全不写低内存——内核从命令行标志 <code>oc.stmon=off</code> 获知此事。</p><h2 id="已声明的-uefi-看门狗限制" tabindex="-1">已声明的 UEFI 看门狗限制 <a class="header-anchor" href="#已声明的-uefi-看门狗限制" aria-label="Permalink to &quot;已声明的 UEFI 看门狗限制&quot;">​</a></h2><p>挂接 i6300ESB PCI 看门狗设备时，UEFI（OVMF）下 OCBL 载荷路径在 槽位扫描后停止；对未修改的 WP07 前加载器的对照重构建以字节一致 的方式复现，说明该缺陷早于 WP-07。不挂该设备时整条 UEFI 监控 路径已实测验证。<strong>BIOS 形态承载完整且经过验证的看门狗机制</strong>， 其链路必须全通（实际全通）。见 <a href="./../../root/KNOWN_ISSUES.html">KNOWN_ISSUES</a> K-02。</p><h2 id="与-ocire-恢复流程的一致性" tabindex="-1">与 OCIRE 恢复流程的一致性 <a class="header-anchor" href="#与-ocire-恢复流程的一致性" aria-label="Permalink to &quot;与 OCIRE 恢复流程的一致性&quot;">​</a></h2><p>菜单所守卫的恢复链是 WP-07 闭环：严格<strong>手动</strong>的 <code>update</code> 命令 （无网络、无定时器）从真实 GPT ESP 读取 <code>\\EFI\\OpenCube\\ocire-update.bin</code> 及其 <code>.sig</code>，用内置 <strong>Ed25519</strong> 公钥验签，刷写双分区恢复盘的<strong>非活动</strong>槽，对回读做散列，再经 LBA 1024 的 A/B 标志扇区布防。坏镜像绝不会替换正在运行的槽—— 接管菜单针对的是<strong>运行系统</strong>失败的情形，而不是更新路径。</p><p>另见：<a href="./ocbl-ab.html">双固件引导与 A/B 槽判定</a>——标志扇区与状态区 语义。</p>`,24)])])}const u=e(c,[["render",r]]);export{b as __pageData,u as default};
